import{_ as e,c as i,o as t,a3 as s}from"./chunks/framework.CoV49S2T.js";const g=JSON.parse('{"title":"安裝","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/installation.md","filePath":"zh-TW/guide/installation.md","lastUpdated":1786595765000}'),r={name:"zh-TW/guide/installation.md"};function l(o,a,n,p,h,c){return t(),i("div",null,[...a[0]||(a[0]=[s(`<h1 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to &quot;安裝&quot;">​</a></h1><p>ClipboardxAI 可用於 macOS。</p><h2 id="下載方式" tabindex="-1">下載方式 <a class="header-anchor" href="#下載方式" aria-label="Permalink to &quot;下載方式&quot;">​</a></h2><h3 id="mac-app-store-推薦" tabindex="-1">Mac App Store（推薦） <a class="header-anchor" href="#mac-app-store-推薦" aria-label="Permalink to &quot;Mac App Store（推薦）&quot;">​</a></h3><ul><li><strong>下載</strong>：在 Mac App Store 中搜尋 <strong>ClipboardxAI</strong>，或從<a href="/zh-TW/">首頁</a>開啟連結。</li><li>Mac App Store 版本提供自動更新，以及與 macOS 的無縫整合。</li></ul><blockquote><p>若尚未提供 Mac App Store 連結，請使用下方 GitHub Releases 版本。</p></blockquote><h3 id="github-releases-替代方案" tabindex="-1">GitHub Releases（替代方案） <a class="header-anchor" href="#github-releases-替代方案" aria-label="Permalink to &quot;GitHub Releases（替代方案）&quot;">​</a></h3><p>你可以直接從 <a href="https://github.com/clipboardxAI" target="_blank" rel="noreferrer">GitHub Releases</a> 下載最新的建置版本。請注意，此版本不會收到自動更新。</p><h2 id="安裝步驟" tabindex="-1">安裝步驟 <a class="header-anchor" href="#安裝步驟" aria-label="Permalink to &quot;安裝步驟&quot;">​</a></h2><h3 id="mac-app-store" tabindex="-1">Mac App Store <a class="header-anchor" href="#mac-app-store" aria-label="Permalink to &quot;Mac App Store&quot;">​</a></h3><ol><li>開啟上方的下載連結，或在 Mac App Store 中搜尋「ClipboardxAI」。</li><li>點擊 <strong>Get（取得）</strong> 下載應用程式。</li><li>應用程式會自動安裝——可從 <strong>Applications（應用程式）</strong> 或 <strong>Launchpad</strong> 啟動它。</li></ol><h3 id="github-releases" tabindex="-1">GitHub Releases <a class="header-anchor" href="#github-releases" aria-label="Permalink to &quot;GitHub Releases&quot;">​</a></h3><ol><li>從 Releases 頁面下載最新的 <code>.dmg</code> 檔。</li><li>雙擊下載的 <code>.dmg</code> 以開啟它。</li><li>將 <code>ClipboardxAI.app</code> 圖示拖曳到你的 <strong>Applications（應用程式）</strong> 資料夾。</li><li>退出掛載的映像檔，並從 <strong>Applications（應用程式）</strong> 開啟應用程式。</li></ol><p>若 macOS 阻止開啟應用程式（Gatekeeper），請開啟 <strong>System Settings → Privacy &amp; Security（系統設定 → 隱私權與安全性）</strong>，點擊 <strong>Open Anyway（仍要開啟）</strong>；或在應用程式上點擊右鍵並選擇 <strong>Open（開啟）</strong>。</p><h2 id="首次啟動" tabindex="-1">首次啟動 <a class="header-anchor" href="#首次啟動" aria-label="Permalink to &quot;首次啟動&quot;">​</a></h2><p>首次啟動時，ClipboardxAI 會引導你完成簡短的設定：</p><ul><li><strong>啟用選單列項目</strong>，讓應用程式常駐於你的選單列。</li><li><strong>授予權限</strong>，以便它在背景監控剪貼簿（請參見<a href="/zh-TW/guide/permissions.html">權限</a>）。</li><li><em>（選用）</em> 若你想要 AI 動作，可在 <strong>Settings → AI（設定 → AI）</strong> 中連接雲端 AI 供應商。</li></ul><p>在出現提示時授予權限。你可以隨時在 <strong>System Settings → Privacy &amp; Security（系統設定 → 隱私權與安全性）</strong> 中變更它們。</p><h2 id="更新" tabindex="-1">更新 <a class="header-anchor" href="#更新" aria-label="Permalink to &quot;更新&quot;">​</a></h2><ul><li><strong>Mac App Store 版本</strong>：由 App Store 自動更新。</li><li><strong>GitHub Releases 版本</strong>：下載較新的版本，並替換 <code>Applications</code> 中的應用程式。</li></ul><h2 id="解除安裝" tabindex="-1">解除安裝 <a class="header-anchor" href="#解除安裝" aria-label="Permalink to &quot;解除安裝&quot;">​</a></h2><p>若要移除 ClipboardxAI：</p><ol><li>退出應用程式。</li><li>將 <code>ClipboardxAI.app</code> 從 <code>Applications</code> 拖曳到垃圾桶。</li><li>（選用）移除本地資料：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.clipboard</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Application</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Scripts/com.w3cub.clipboard</span></span></code></pre></div><h2 id="系統需求" tabindex="-1">系統需求 <a class="header-anchor" href="#系統需求" aria-label="Permalink to &quot;系統需求&quot;">​</a></h2><ul><li><strong>macOS</strong>：Sonoma（14）或以上版本</li><li><strong>CPU</strong>：Apple Silicon（M 系列）或 Intel（64 位元）</li><li><strong>記憶體</strong>：最低 4 GB，建議 8 GB</li><li><strong>儲存空間</strong>：約 ~50 MB</li></ul><h2 id="疑難排解" tabindex="-1">疑難排解 <a class="header-anchor" href="#疑難排解" aria-label="Permalink to &quot;疑難排解&quot;">​</a></h2><p>若你在安裝過程中遇到問題：</p><ul><li><strong>macOS 封鎖應用程式</strong>：開啟 <strong>System Settings → Privacy &amp; Security（系統設定 → 隱私權與安全性）</strong>，點擊 <strong>Open Anyway（仍要開啟）</strong>。</li><li><strong>公證（Notarization）警告</strong>：請從 Mac App Store 下載已簽署／公證的建置版本。</li></ul><p>如需更多協助，請參閱<a href="/zh-TW/guide/troubleshooting.html">疑難排解指南</a>。</p>`,30)])])}const u=e(r,[["render",l]]);export{g as __pageData,u as default};
